def _iter_loop_var_pp_accesses(
    forloop: ast.For, pp_modules: set[str]
) -> list[tuple[ast.Attribute, str, str]]:
    """
    For a ``for <var> in self.<pp_module>:`` loop over a PP-managed submodule, yield the non-standard attribute
    accesses performed on the loop variable inside the loop body.

    Returns tuples of ``(attribute_node, access_expression, self_reference)`` where ``access_expression`` is e.g.
    ``layer.some_attr`` and ``self_reference`` is the full reference to the iterated module, e.g. ``self.layers``.
    """
    if not (_is_self_attribute(forloop.iter) and isinstance(forloop.target, ast.Name)):
        return []
    module_name = forloop.iter.attr
    if module_name not in pp_modules:
        return []

    loop_var = forloop.target.id
    self_reference = full_name(forloop.iter)

    accesses: list[tuple[ast.Attribute, str, str]] = []
    for statement in forloop.body:
        for sub_node in ast.walk(statement):
            if (
                isinstance(sub_node, ast.Attribute)
                and isinstance(sub_node.value, ast.Name)
                and sub_node.value.id == loop_var
                and sub_node.attr not in _STANDARD_NN_MODULE_ATTRS
            ):
                accesses.append((sub_node, f"{loop_var}.{sub_node.attr}", self_reference))
    return accesses


def trf011_check_pp_plan_attribute_access(
    tree: ast.Module, file_path: Path, source_lines: list[str], violations: list[Violation], rule_id: str
) -> list[Violation]:
    """
    Flag unsafe attribute accesses on submodules that are managed by a model's pipeline parallelism (PP) plan.

    Under pipeline parallelism, PP-managed submodules may be wrapped, replaced, or absent on a given rank. Reaching
    into their non-standard ``nn.Module`` attributes from ``forward`` is therefore unsafe. We flag both loop variables
    iterating over such a submodule (e.g. ``for layer in self.layers: layer.custom_attr``) and direct accesses of the
    form ``self.<pp_module>.<attr>``.
    """
    pp_plan_by_dir = _PP_PLAN_MODULES_BY_MODEL_DIR
    if not pp_plan_by_dir:
        return violations

    model_dir = _model_dir_name(file_path)
    if model_dir is None:
        return violations

    pp_modules = pp_plan_by_dir.get(model_dir)
    if not pp_modules:
        return violations

    class_to_bases = _collect_class_bases(tree)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not _inherits_pretrained_model(node.name, class_to_bases):
            continue

        forward_method = _class_methods(node).get("forward")
        if forward_method is None:
            continue

        # Case 1: loop variables iterating over a PP-managed submodule.
        for sub_node in ast.walk(forward_method):
            if not isinstance(sub_node, ast.For):
                continue
            for attribute_node, access_expr, self_reference in _iter_loop_var_pp_accesses(sub_node, pp_modules):
                if _has_rule_suppression(source_lines, rule_id, attribute_node.lineno):
                    continue
                violations.append(
                    Violation(
                        file_path=file_path,
                        line_number=attribute_node.lineno,
                        rule_id=rule_id,
                        message=(
                            f"{rule_id}: `{access_expr}` accesses a non-standard attribute on a submodule of "
                            f"`{self_reference}`, which is managed by the pipeline parallelism plan. Accessing custom "
                            "attributes on PP-managed submodules is unsafe."
                        ),
                    )
                )

        # Case 2: direct `self.<pp_module>.<attr>` accesses.
        for sub_node in ast.walk(forward_method):
            if not (isinstance(sub_node, ast.Attribute) and _is_self_attribute(sub_node.value)):
                continue
            pp_module_name = sub_node.value.attr
            # `self.config.<anything>` is always safe and must never be flagged.
            if pp_module_name == "config":
                continue
            if pp_module_name not in pp_modules:
                continue
            if sub_node.attr in _STANDARD_NN_MODULE_ATTRS:
                continue
            if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                continue

            access_chain = full_name(sub_node)
            violations.append(
                Violation(
                    file_path=file_path,
                    line_number=sub_node.lineno,
                    rule_id=rule_id,
                    message=(
                        f"{rule_id}: `{access_chain}` accesses a non-standard attribute on `self.{pp_module_name}`, "
                        "which is managed by the pipeline parallelism plan. Accessing custom attributes on PP-managed "
                        "submodules is unsafe."
                    ),
                )
            )

    return violations


